glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform StarryNight {
  vec4 starParams;
  vec4 shineParams;
  vec4 bgStarParams;
  vec4 colorBackground;
  vec4 nodeSize;
};
uniform sampler2D gradientA;
uniform sampler2D gradientB;
float rand(vec2 st) {
  return fract(sin(dot(st.xy, vec2(bgStarParams.w + 12.9898, 78.233))) * 43758.5453123);
}
float remap(float prob, float starValue) {
  return (starValue - prob) / (1.0 - prob);
}
vec4 frag() {
  vec4 base = CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
  vec4 overlay = vec4(0.0);
  float prob = 1.0 - starParams.z;
  float travelx = cc_time.x * shineParams.z;
  float travely = cc_time.x * shineParams.w;
  vec2 fragCoord = uv0 * nodeSize.xy;
  int iterations = int(starParams.x);
  for (int i = 1; i < 11; i++) {
    if (i > iterations) break;
    float sz = starParams.y / float(i);
    vec2 pos = vec2(
      floor(fragCoord.x / sz + travelx),
      floor(fragCoord.y / sz + travely)
    );
    float starValue = rand(pos);
    if (starValue > prob) {
      vec2 center = sz * pos + vec2(sz, sz) * 0.5;
      float t = 0.9 + 0.2
        * sin(cc_time.x * shineParams.x + (starValue - prob) / (1.0 - prob) * 45.0);
      vec2 mc = vec2(fragCoord.x + travelx * sz, fragCoord.y + travely * sz);
      float c = 1.0 - distance(mc, center) / (0.5 * sz);
      c = t * t * starParams.w / float(i)
        / clamp(distance(mc.y, center.y), 0.5, sz / 2.0 - 1.0)
        / clamp(distance(mc.x, center.x), 0.5, sz / 2.0 - 1.0);
      vec4 cmap = texture(gradientA, vec2(remap(prob, starValue), 0.5));
      overlay.rgb += cmap.rgb * c * (1.0 - shineParams.y);
    }
  }
  if (rand(uv0 / 20.0) > bgStarParams.x) {
    float r = rand(uv0);
    float c = r * (0.85
      * sin(cc_time.x * bgStarParams.y * (r * 5.0) + 720.0 * r) + 0.95);
    vec4 cmap = texture(gradientB, vec2(r, 0.5));
    overlay.rgb += c * cmap.rgb * (1.0 - bgStarParams.z);
  }
  vec3 skyTint = colorBackground.rgb * colorBackground.a;
  vec4 o;
  o.rgb = base.rgb + skyTint * 0.8 + overlay.rgb;
  o.a = base.a;
  ALPHA_TEST(o);
  o *= color;
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

